@@ -0,0 +1,88 @@
+// @ts-check
+
+import {Effect, PolicyStatement} from 'aws-cdk-lib/aws-iam';
+import {LogFormat} from 'aws-cdk-lib/aws-lambda';
+import {DatadogLambda} from 'datadog-cdk-constructs-v2';
+import * as dotenv from 'dotenv';
+import type {SSTConfig} from 'sst';
+import type {App} from 'sst/constructs';
+import {Stack} from 'sst/constructs';
+import {AppConfig} from './stacks/AppConfig';
+import {BffApi} from './stacks/BffApi';
+import {Site} from './stacks/Site';
+dotenv.config();
+
+export const appName = `forms-app`;
+const envSet = [`dev`, `site`, `stage`, `prod`];
+const config: SSTConfig = {
+  config(_input) {
+    return {
+      name: process.env.FEATURE_APP_NAME || appName,
+      region: `eu-central-1`,
+      stage: process.env.STAGE ?? process.env.TARGET ?? `dev`,
+    };
+  },
+  async stacks(app) {
+    addDatadogPermissions(app);
+    app.setDefaultFunctionProps({
+      runtime: `nodejs18.x`,
+      architecture: `arm_64`,
+      logFormat: LogFormat.JSON,
+      logRetention: app.stage === `prod` ? `two_months` : `one_month`,
+      timeout: `30 seconds`,
+    });
+
+    app.stack(AppConfig);
+    app.stack(BffApi);
+    if (envSet.includes(app.stage)) {
+      app.stack(Site);
+    }
+
+    await app.finish();
+    app.node.children.forEach((child) => {
+      if (child instanceof Stack) {
+        addDatadogConstruct(app, child);
+      }
+    });
+  },
+};
+
+const apiKeySecretArn = `arn:aws:secretsmanager:eu-central-1:586794439527:secret:services/datadog/apiKey-G1HokC`;
+
+function addDatadogConstruct(app: App, stack: Stack) {
+  const datadog = new DatadogLambda(stack, `datadog`, {
+    nodeLayerVersion: 108, // https://github.com/Datadog/datadog-lambda-js/releases
+    extensionLayerVersion: 56, // https://github.com/Datadog/datadog-lambda-extension/releases
+    site: `datadoghq.eu`,
+    apiKeySecretArn,
+    enableDatadogTracing: true,
+    enableMergeXrayTraces: true,
+    enableDatadogLogs: true,
+    enableProfiling: true,
+    enableColdStartTracing: true,
+    env: app.stage,
+    service: app.name,
+    redirectHandler: app.stage === `prod`,
+    addLayers: app.stage === `prod`,
+  });
+  datadog.addLambdaFunctions(stack.getAllFunctions());
+}
+
+function addDatadogPermissions(app: App) {
+  app.addDefaultFunctionPermissions([
+    new PolicyStatement({
+      effect: Effect.ALLOW,
+      resources: [apiKeySecretArn],
+      actions: [`secretsmanager:GetSecretValue`],
+    }),
+  ]);
+
+  app.setDefaultFunctionProps({
+    nodejs: {
+      esbuild: {
+        external: [`dd-trace`, `datadog-lambda-js`],
+      },
+    },
+  });
+}
+export default config;

