+import dotenv from 'dotenv';
+import type {Configuration} from 'webpack';
+import {getFeatureAppConfig, getWebAppConfig} from './webpack';
+dotenv.config();
+interface EnvVariables {
+  [key: string]: string | undefined;
+}
+
+const featureLocalAppName = `forms-app`;
+export default (_: EnvVariables, argv: Configuration) => {
+  const target = process.env.TARGET || `dev`;
+  const stage = process.env.STAGE ?? `dev`;
+  const featureAppName = process.env.FEATURE_APP_NAME ?? featureLocalAppName;
+  const hostedZone =
+    process.env.AWS_HOSTED_ZONE_NAME ??
+    `dev.${featureAppName}.feature-app.srv.smart.com`;
+
+  console.log(`argv`, argv, _);
+  const mode = argv.mode ?? `development`;
+  const baseUrl = `/__app__/${featureAppName}/${target}`;
+  const privateBaseUrl = baseUrl.replace(`__app__`, `__app-private__`);
+  const featureAppConfig = getFeatureAppConfig({
+    mode,
+    baseUrl,
+    target,
+    stage,
+    featureAppName,
+    hostedZone,
+  });
+
+  const webConfig = getWebAppConfig({
+    mode,
+    stage,
+    target,
+    baseUrl,
+    privateBaseUrl,
+    featureAppName,
+    hostedZone,
+  });
+
+  return [featureAppConfig, webConfig];
+};

